    runs.flatMap((run) => {
      let start = run.start;
      return run.ops.map((op) => {
        const end = op[0] === 'L' ? op.slice(1) : op.slice(3);
        const control =
          op[0] === 'Q' ? op.slice(1, 3) : [(start[0] + end[0]) / 2, (start[1] + end[1]) / 2];
